    const inc = includes.length
      ? included(
          books.map((b) => bookResource(b)),
          fields,
        )
      : undefined;

    res.type('application/vnd.api+json');
    return listDocument('/authors', sp, page, total, data, fields, inc);
  }

  @Get(':id')
