cat > /tmp/restore.mjs <<'EOF'
import pg from '/work/node_modules/pg/lib/index.js';
import fs from 'node:fs';
const snap = JSON.parse(fs.readFileSync('/tmp/snapshot.json', 'utf8'));
const c = new pg.Client('postgres://eval_rw:eval_rw@postgres:5432/llmapi_eval');
await c.connect();
await c.query('BEGIN');
const keepP = snap.purchase.map((r) => r.id);
await c.query('DELETE FROM purchase_line WHERE purchase_id <> ALL($1::int[])', [keepP]);
await c.query('DELETE FROM purchase WHERE id <> ALL($1::int[])', [keepP]);
for (const b of snap.book) {
  await c.query('UPDATE book SET title=$2, author_id=$3, published=$4, price_cents=$5, published_at=$6, stock=$7 WHERE id=$1',
    [b.id, b.title, b.author_id, b.published, b.price_cents, b.published_at, b.stock]);
}
await c.query('COMMIT');
await c.query('SELECT setval(\'purchase_id_seq\', $1, $2)', [snap.seq.last_value, snap.seq.is_called]);
await c.query('SELECT setval(\'purchase_line_id_seq\', $1, $2)', [snap.lseq.last_value, snap.lseq.is_called]);
// verify
const cur = {};
for (const t of ['book','purchase','purchase_line']) cur[t] = (await c.query(`select * from ${t} order by id`)).rows;
const norm = (x) => JSON.stringify(x, (k, v) => (v instanceof Date ? v.toISOString() : v));
for (const t of ['book','purchase','purchase_line']) {
  const a = norm(snap[t]); const b = norm(cur[t]);
  console.log(t, a === b ? 'MATCH' : 'DIFF', cur[t].length);
}
await c.end();
EOF
node /tmp/restore.mjs
